import pandas as pd, numpy as np, os, json, math, sys, random, itertools, textwrap, typing, datetime, collections, warnings, pathlib, functools, re, decimal, fractions, decimal, statistics, inspect, pprint, copy, string, hashlib
from math import isnan

# paths provided
DATASET_PATH = 'chunks_csv/moran_local_no2crime_no2_Q4_2023.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

# 1. Load data
df = pd.read_csv(DATASET_PATH)
adj = pd.read_csv(ADJACENCY_PATH)

# keep boroughs with actual NO2 value
df = df.dropna(subset=['value']).reset_index(drop=True)
values = df.set_index('borough')['value']
boroughs = values.index.tolist()

# 2. Build weight matrix (row-standardised)
neighbors_dict = {b: set() for b in boroughs}
for _, row in adj.iterrows():
    b = row['borough']; n = row['neighbor']
    if b in neighbors_dict and n in neighbors_dict:
        neighbors_dict[b].add(n)
        # adjacency is undirected – add both directions
        neighbors_dict[n].add(b)

# Row-standardised weights
W = {}
for b in boroughs:
    nbs = neighbors_dict[b]
    if len(nbs)==0:
        W[b] = {}
    else:
        w = 1/len(nbs)
        W[b] = {n:w for n in nbs}

# 3. z-scores
x = values.values
mean = x.mean()
std = x.std(ddof=0)
z = (x - mean)/std
z_series = pd.Series(z, index=boroughs)

# helper: spatial lag of z
lag_z = {}
for b in boroughs:
    lz = sum(W[b].get(n,0)*z_series[n] for n in W[b])
    lag_z[b] = lz

# 4. Local Moran's I
I = {}
for b in boroughs:
    I[b] = z_series[b]*lag_z[b]

# 5. Permutation test (999 perms)
perms = 999
rng = np.random.default_rng(42)
I_perm_counts = {b:0 for b in boroughs}

z_array = z_series.values.copy()
for _ in range(perms):
    rng.shuffle(z_array)
    z_perm = pd.Series(z_array, index=boroughs)
    for b in boroughs:
        lag = sum(W[b].get(n,0)*z_perm[n] for n in W[b])
        I_perm = z_perm[b]*lag
        if abs(I_perm) >= abs(I[b]) - 1e-12:
            I_perm_counts[b] += 1

p_values = {b:(I_perm_counts[b]+1)/(perms+1) for b in boroughs}

# 6. Determine HH / LL significant at 0.05
results=[]
for b in boroughs:
    if p_values[b] < 0.05 and I[b] > 0:
        if z_series[b] > 0 and lag_z[b] > 0:
            results.append((b,'HH',I[b]))
        elif z_series[b] < 0 and lag_z[b] < 0:
            results.append((b,'LL',I[b]))

# 7. Print evidence
for b,typ,val in results:
    print(f"{b}: {typ}, I={val:.3f}, p={p_values[b]:.3f}")

# 8. Final answer line
if results:
    parts = [f"{b} ({typ}, I={val:.3f})" for b,typ,val in results]
    final = "FINAL ANSWER: " + ", ".join(parts)
else:
    final = "FINAL ANSWER: none"

print(final)
